    set(controlbarIsOpened, false);


if (device.desktop,
	set(layer[controlbarbtn_in].visible, false);
	set(layer[controlbarbtn_out].visible, false);
);
if (device.desktop,
	set(layer[controlbarbtn_up].visible, false);
	set(layer[controlbarbtn_down].visible, false);
);
