    set(controlbarIsOpened, true);

	set(layer[controlbar_menu_bg].visible, true);

	if (device.desktop,
	set(layer[controlbarbtn_control].visible, true);
);

if (device.desktop,
	set(layer[controlbarbtn_in].visible, true);
	set(layer[controlbarbtn_out].visible, true);
);

