	set(layer[controlbarbtn_left].visible, true);
	set(layer[controlbarbtn_right].visible, true);
);
	controlbarupdateFullscreenButtons();
	controlbarupdateHelpButtons();
	controlbarupdateResolutionButtons();

	controlbarupdateAutorotationButtons();

	controlbarupdateSoundButtons();

	controlbarupdateAutoguideSoundButtons();


	set(layer[controlbarbtn_autoplay].visible, false);
	set(layer[controlbarbtn_autoplay_off].visible, false);




