if (device.desktop,
  set(layer[controlbarhelpScreenFg].displayed,false);
  tween(layer[controlbarhelpScreenFg].rotate,  90, 1, easeOutQuad, set(layer[helpScreenFg].visible,false););
  tween(layer[controlbarhelpScreenFg].x, -100%, 1);
  tween(layer[controlbarhelpScreenBg].rotate, -90, 1, easeOutQuad, set(layer[helpScreenBg].visible,false););
  tween(layer[controlbarhelpScreenBg].x, 100%, 1);
  controlbarupdateHelpButtons();
);

if (device.desktop,
	set(controlbarDisplayHelpButtons, false);
	if (controlbarIsOpened, set(controlbarDisplayHelpButtons, true););
	if (controlbarDisplayHelpButtons,
		controlbarShowHelpButtons();
	,
		controlbarHideHelpButtons();
	);
,
	controlbarHideHelpButtons();
);

if (device.desktop,
	set(controlbarDisplayResolutionButtons, false);

	if (controlbarIsOpened, set(controlbarDisplayResolutionButtons, true););

	if (controlbarDisplayResolutionButtons,
		controlbarShowResolutionButtons();
	,
		controlbarHideResolutionButtons();
	);
,
	controlbarHideResolutionButtons();
);

if (device.fullscreensupport,
	if(tour_fullscreen,
		set(layer[controlbarbtn_openfs].visible , false);
		set(layer[controlbarbtn_closefs].visible, true);
	,
		set(layer[controlbarbtn_openfs].visible ,true);
		set(layer[controlbarbtn_closefs].visible,false);
	);
,
	controlbarHideFullscreenButtons();
);

