	controlbarShowAutoguideSoundButtons();
,
	controlbarHideAutoguideSoundButtons();
);


set(controlbarbutton_pos, 0);


  if (device.desktop,
    set(layer[controlbarbtn_display_help].x, get(controlbarbutton_pos));
    set(layer[controlbarbtn_close_help].x  , get(controlbarbutton_pos));
    inc(controlbarbutton_pos, 43);
  ); 

  if (device.desktop,

  );

  if (device.fullscreensupport,
    set(layer[controlbarbtn_openfs].x , get(controlbarbutton_pos));
    set(layer[controlbarbtn_closefs].x, get(controlbarbutton_pos));
    inc(controlbarbutton_pos, 43);
  );

  set(layer[controlbarbtn_autorotate_on].x , get(controlbarbutton_pos));
  set(layer[controlbarbtn_autorotate_off].x, get(controlbarbutton_pos));
  inc(controlbarbutton_pos, 43);


  set(layer[controlbarbtn_sound_on].x , get(controlbarbutton_pos));
  set(layer[controlbarbtn_sound_off].x, get(controlbarbutton_pos));
  inc(controlbarbutton_pos, 43);


  set(layer[controlbarbtn_autoguide_on].x , get(controlbarbutton_pos));
  set(layer[controlbarbtn_autoguide_off].x, get(controlbarbutton_pos));
  inc(controlbarbutton_pos, 43);

  if (device.desktop,
   set(layer[controlbarbtn_control].x , get(controlbarbutton_pos));
  );

  if (device.desktop,
    set(layer[controlbarbtn_left].x, 40);

  	set(layer[controlbarbtn_right].x,0);             

    set(layer[controlbarbtn_down].x, 80);

    set(layer[controlbarbtn_up].x, 120);

    set(layer[controlbarbtn_out].x, 160);

    set(layer[controlbarbtn_in].x, 200);
  );



  inc(controlbarbutton_pos, 43);



  set(layer[controlbarbtn_autoplay].x , get(controlbarbutton_pos));
  set(layer[controlbarbtn_autoplay_off].x, get(controlbarbutton_pos));
  inc(controlbarbutton_pos, 43);

  dec(controlbarbutton_pos, 5);

  set(controlbarbackgroundwidthwhenopened, get(controlbarbutton_pos));
  set(layer[controlbar_menu_bg].width, get(controlbarbackgroundwidthwhenopened));

if(%1== floor_1,
	set(layer[floor_1].url,%FIRSTXML%/skin/1_floor_active.png);
	set(layer[floor_2].url,%FIRSTXML%/skin/2_floor.png);
	set(layer[floor_3].url,%FIRSTXML%/skin/3_floor.png);


	set(layer[map_exhibition_1].zorder,16);
	set(layer[map_exhibition_2].zorder,15);
	set(layer[map_exhibition].zorder,14);
);

if(%1== floor_2,		
	set(layer[floor_2].url,%FIRSTXML%/skin/2_floor_active.png);
	set(layer[floor_1].url,%FIRSTXML%/skin/1_floor.png);
	set(layer[floor_3].url,%FIRSTXML%/skin/3_floor.png);

	set(layer[map_exhibition_2].zorder,16);
	set(layer[map_exhibition_1].zorder,15);
	set(layer[map_exhibition].zorder,14);
);

if(%1== floor_3,
	set(layer[floor_3].url,%FIRSTXML%/skin/3_floor_active.png);
	set(layer[floor_2].url,%FIRSTXML%/skin/2_floor.png);
	set(layer[floor_1].url,%FIRSTXML%/skin/1_floor.png);

	set(layer[map_exhibition_1].zorder,14);
	set(layer[map_exhibition_2].zorder,15);
	set(layer[map_exhibition].zorder,16);
);

set(tour_soundson, false);
events.dispatch(stoptoursoundsevent);
set(plugin[data].soundOn, false); 
stop_background_sound();

if(
	%1 == none, 
		set(plugin[backgroundinterface].background,%1,0); 
	, if(
		plugin[backgroundinterface].background == %1, 
			if (
				%3 == forcesounds, 
					playsound(backgroundsound,%1,%2,0); ) 
				, 
					playsound(backgroundsound,%1,%2); 
					set(plugin[backgroundinterface].background,%1,0
				);
		);
);

if(get(plugin[data].autoplay),
	if(
		%1 == none,
			set(plugin[autoguideinterface].background,%1,1,nextOnFinishSound()); 
		, if(
			plugin[autoguideinterface].background == %1,
				if (
					%3 == forcesounds, 
						playsound(autoguidesound,%1,1,nextOnFinishSound()); 
					);
			, 
				playsound(autoguidesound,%1,1,nextOnFinishSound()); 
				set(plugin[autoguideinterface].background,%1);
			) 
	)

	,

	if(
		%1 == none,
			set(plugin[autoguideinterface].background,%1,0); 
		, if(
			plugin[autoguideinterface].background == %1,
				if (
					%3 == forcesounds, 
						playsound(autoguidesound,%1,%2); 
					);
			, 
				playsound(autoguidesound,%1,%2); 
				set(plugin[autoguideinterface].background,%1);
			) 
	);
);

 	if(layer[%1].visible == false,
		if(%1== map_exhibition,	showbackground_size();closegraphics_background(););
		if(%1== menu_exhibition, showbackground_size();closegraphics_background(););
		if(%1== menu_exhibition_en, showbackground_size();closegraphics_background(););
		if(%1== menu_share,
			if(layer[toprightbg].y == 200,
				hidemenuphongtruyenthong();
				hidebackground_size();
			);
		);

 		set(layer[%1].visible,true);
		tween(layer[%1].alpha, 1, 0.3);
	,
		tween(layer[%1].alpha, 0, 0.3,default,set(layer[%1].visible,false));
		hidebackground_size();
	);

